<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue';import {api} from './api';import Icon from './Icon.vue';
const emit=defineEmits(['notify','error']);const connected=ref(false),busy=ref(false),error=ref(''),flow=ref<any>({phase:'idle',url:''}),projects=ref<any[]>([]),form=ref({projectId:'',url:'',title:''}),importing=ref(false);let timer:any;
async function refresh(){const [settings,state]=await Promise.all([api('/settings'),api('/lark/status')]);connected.value=settings.lark.connected;const old=flow.value.phase;flow.value=state;if(state.phase==='complete'&&old!=='complete')emit('notify','Lark 授权已完成，可开始导入与导出文档');}
async function connect(){busy.value=true;error.value='';const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;try{flow.value=await api('/lark/connect','POST',{});if(flow.value.url&&popup)popup.location.href=flow.value.url;else popup?.close();}catch(e:any){popup?.close();error.value=e.message;}finally{busy.value=false;}}
async function cancel(){try{await api('/lark/cancel','POST',{});flow.value={phase:'idle',url:''};}catch(e:any){error.value=e.message;}}
async function disconnect(){if(!confirm('解除本工作台的 Lark 绑定？已导入的文档会保留。'))return;try{await api('/lark/disconnect','POST',{});await refresh();emit('notify','已解除本地绑定；如需撤回 Lark 平台权限，请在 Lark 授权管理中操作');}catch(e:any){error.value=e.message;}}
async function importDoc(){importing.value=true;error.value='';try{await api('/projects/'+form.value.projectId+'/lark/import','POST',{url:form.value.url,title:form.value.title});form.value.url='';form.value.title='';emit('notify','文档已导入所选项目，可在产品文档中编辑');}catch(e:any){error.value=e.message;}finally{importing.value=false;}}
onMounted(async()=>{try{await refresh();projects.value=(await api('/projects')).filter((p:any)=>['owner','editor'].includes(p.role));form.value.projectId=projects.value[0]?.id||'';}catch(e:any){error.value=e.message;}timer=setInterval(()=>{if(['registering','authorizing','starting'].includes(flow.value.phase))refresh().catch(e=>error.value=e.message);},3000);});onUnmounted(()=>clearInterval(timer));
</script><template><div class="lark-settings"><div class="integration-heading"><span class="integration-logo lark">L</span><div><h2>连接 Lark 文档</h2><p>点击授权链接，连接你的国际版飞书文档。</p></div><span class="badge" :class="connected?'green':''">{{connected?'已绑定':'未绑定'}}</span></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><section class="lark-auth-card"><span class="lark-auth-icon"><Icon name="Link" :size="28"/></span><h3>{{connected?'你的 Lark 文档已就绪':'授权一次，连接整个文档工作流'}}</h3><p>不需要复制 Token，也不用填写应用密钥。<br>在 Lark 官方页面确认授权，返回后自动完成绑定。</p><div class="lark-permissions"><span><Icon name="Check" :size="14"/>读取需求文档</span><span><Icon name="Check" :size="14"/>创建交付文档</span><span><Icon name="Check" :size="14"/>保持授权连接</span></div><div v-if="['idle','complete','failed','expired','cancelled'].includes(flow.phase)"><button class="primary" @click="connect" :disabled="busy"><Icon :name="busy?'LoaderCircle':'ExternalLink'" :class="{spin:busy}" :size="17"/>{{busy?'正在获取授权链接…':connected?'重新授权':'连接我的 Lark'}}</button><button v-if="connected" class="text-button" @click="disconnect">解除绑定</button></div><div v-else class="authorization-progress"><div class="auth-steps"><span :class="{done:flow.phase==='authorizing'}">1 连接应用</span><Icon name="ChevronRight" :size="15"/><span :class="{active:flow.phase==='authorizing'}">2 授权文档</span><Icon name="ChevronRight" :size="15"/><span>3 完成绑定</span></div><p>{{flow.message}}</p><a v-if="flow.url" class="primary auth-link" :href="flow.url" target="_blank" rel="noopener noreferrer">{{flow.phase==='registering'?'打开 Lark，确认应用连接':'打开 Lark，授权文档访问'}}<Icon name="ArrowUpRight" :size="17"/></a><div class="auth-wait"><Icon name="LoaderCircle" class="spin" :size="15"/>等待你在 Lark 完成确认 <button class="text-button" @click="cancel">取消</button></div></div><p class="error-inline" v-if="['failed','expired'].includes(flow.phase)">{{flow.message}}</p><small>权限由你的 Lark 账号和组织策略决定；本工作台仅使用你确认的文档权限。</small></section><form class="settings-form lark-import" @submit.prevent="importDoc"><div class="section-title"><div><h3>将 Lark 需求导入项目</h3><p class="muted">保留文档来源，后续可在产品文档中继续编辑和创作。</p></div><Icon name="FileText"/></div><div class="form-grid"><label>目标项目<select v-model="form.projectId" required :disabled="!connected"><option value="">选择项目</option><option v-for="p in projects" :value="p.id">{{p.name}}</option></select></label><label>文档标题<input v-model="form.title" required :disabled="!connected" placeholder="导入后显示的文档名称"/></label></div><label>Lark 文档链接<input v-model="form.url" type="url" required :disabled="!connected" placeholder="https://你的组织.larksuite.com/docx/..."/></label><button class="secondary" :disabled="!connected||importing||!form.projectId">{{importing?'正在读取文档…':'读取并导入项目'}}</button><p v-if="!connected" class="muted">完成上方授权后，即可导入文档，无需另行填写凭据。</p></form></div></template>
